VALUES ('bp-pingo-doce', 1, 'bp-pingo-doce', 'Poupa Mais (BP × Pingo Doce)', '€2 of BP fuel credit for every €40 spent at Pingo Doce with the Poupa Mais card, redeemable on a later fill, capped at 25% of the fill value and €20 per day.', NULL, NULL, 0, 'card_partner', 'BP', '["PINGO DOCE"]', '["BP"]', '["BP"]', '["poupa_mais_card","spend:pingodoce_40"]', 0, 'coupon', 'eur_per_fill', 2, 'sum', NULL, NULL, 'always', '[]', '[]', NULL, NULL, NULL, NULL, 'high', 'https://www.pingodoce.pt/parcerias/bp/', '2026-10-23', NULL, 'auto', 'Poupa Mais card: every 40 EUR spent at Pingo Doce (mainland and Madeira) accrues 2 EUR of BP fuel credit, valid until the end of the following month. Redemption is capped at 25% of the fill value and 20 EUR per day, which does not bind a typical 50 L fill; per-fill caps are not modelled beyond that.', '2026-10-23')
