VALUES ('intermarche-first-wednesday', 1, 'intermarche-first-wednesday', 'Primeira quarta-feira (Cartão Poupança)', '€10 in Cartão Poupança when fuelling at least €50 at participating Intermarché stations on the first Wednesday of each month; the credit must then be spent in Intermarché stores from the following Thursday to Sunday.', NULL, NULL, 0, 'campaign', 'INTERMARCHÉ', '[]', '["INTERMARCHÉ"]', '["Intermarché","intermarche"]', '["intermarche_card","spend:fuel_50"]', 0, 'cashback', 'eur_per_fill', 10, 'sum', NULL, NULL, 'nth_weekday_of_month', '[]', '[]', 1, 3, NULL, NULL, 'medium', 'https://www.sabado.pt/dinheiro/detalhe/guia-de-descontos-nos-combustiveis-para-poupar-da-proxima-vez-que-for-abastecer', '2026-10-23', NULL, 'auto', 'Third-party guide only: it describes a recurring first-Wednesday offer, while Intermarché promo blogs report one-off Wednesday dates. Kept at medium confidence so it is never applied to an effective price; revisit if Intermarché publishes standing terms.', '2026-10-23')
