VALUES ('repsol-lidl-plus-immediate', 1, 'repsol-lidl-plus', 'Lidl Plus × Repsol', '0,06 €/litro off at Repsol stations when the Lidl Plus virtual card is presented at the till, which becomes 0,10 €/litro in total when the Lidl Plus account is also linked to a My Repsol card.', 'linked', 'Lidl Plus + My Repsol', 2, 'card_partner', 'REPSOL', '["LIDL"]', '["REPSOL"]', '["Repsol"]', '["lidl_plus","my_repsol"]', 0, 'instant', 'cents_per_litre', 6, 'sum', NULL, NULL, 'always', '[]', '[]', NULL, NULL, '2026-01-01', '2026-12-31', 'high', 'https://www.lidl.pt/static/assets/Reg_CampanhaLidlRepsol_1Jana31Dez_26_PT-1874241.pdf', '2026-10-23', NULL, 'manual', 'Regulation clause 1.1: 0,10 EUR/litre in total, of which 0,06 EUR/litre immediate and 0,04 EUR/litre as My Repsol balance, when the Lidl Plus app is linked to My Repsol. Also grants a 3 EUR Lidl coupon for every 30 EUR of fuel (max 3 per day, 15-day validity), which is a Lidl store coupon and is therefore described but not priced into the fuel effective price. Valid in mainland Portugal and Madeira; Azores excluded.', '2026-10-23')
